import{_ as t,o as n,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy player flow","description":"Updated November 11, 2026 for the lesson-collection GDD.\\nThis is the intended experience, not evidence that its scenes or screens exist.\\nCurrent work is documentation and setu","frontmatter":{"title":"Chainy player flow","description":"Updated November 11, 2026 for the lesson-collection GDD.\\nThis is the intended experience, not evidence that its scenes or screens exist.\\nCurrent work is documentation and setu","source":"docs/design/app-flow.md","category":"Game & system design","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/design/app-flow.md","filePath":"content/docs/design/app-flow.md"}'),i={name:"content/docs/design/app-flow.md"};function a(s,e,d,l,c,p){return n(),r("div",null,[...e[0]||(e[0]=[o(`<div><h1 id="chainy-player-flow">Chainy player flow<a class="header-anchor" href="#chainy-player-flow" aria-label="Link to this section">​</a></h1><p>Updated November 11, 2026 for the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a>. This is the intended experience, not evidence that its scenes or screens exist. <strong>Current work is documentation and setup only; final owner approval is required before development.</strong> Sherwin owns experience decisions, Christian owns gameplay behavior, Miguel owns game UI implementation, and Sean owns authored documentation.</p><h2 id="main-journey">Main journey<a class="header-anchor" href="#main-journey" aria-label="Link to this section">​</a></h2><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  Menu[Main menu] --&gt; Select[World selection]
  Select --&gt;|Unlocked world only| Load[Load local profile and world checkpoint]
  Load --&gt;|First visit| Tutorial[Tutorial NPC and controls orientation]
  Load --&gt;|Returning visit| Explore[Explore island and follow current quest]
  Tutorial --&gt; Explore
  Explore --&gt; Collect[Inspect ordinary lesson object and record it]
  Explore --&gt; Steps[Complete ordered item, NPC, facility prerequisites]
  Steps --&gt; Mini[Dedicated minigame scene]
  Mini --&gt;|Wrong action or Retry| Mini
  Mini --&gt;|Exit without success| Explore
  Mini --&gt;|Success| Save[Save entry and lesson checkpoint]
  Collect --&gt; Save
  Save --&gt;|Failed save| Error[Keep pending result and offer Retry Save]
  Error --&gt; Save
  Save --&gt;|Fewer than 13 entries| Explore
  Save --&gt;|All 13 entries| Ready[Collection complete: review required]
  Ready --&gt; Review[Required world review]
  Ready --&gt;|Explore more| Explore
  Review --&gt;|Leave before completion| Select
  Review --&gt;|Approved completion rule met| Finish[Save world completion and next unlock]
  Finish --&gt;|Failed save| Review
  Finish --&gt;|Web3 or Blockchain| Select
  Finish --&gt;|AI| Journey[Journey complete]
  Journey --&gt; Select
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>World access is sequential: only Web3 is initially open; completing its required review unlocks Blockchain, and completing Blockchain&#39;s review unlocks AI. Completing thirteen entries alone does not unlock another island. Leaving a required review unfinished preserves the collection but leaves world completion and the next unlock pending. Completed worlds remain available for revisits.</p><h2 id="screen-and-state-contract">Screen and state contract<a class="header-anchor" href="#screen-and-state-contract" aria-label="Link to this section">​</a></h2><table><thead><tr><th>State</th><th>Planned behavior and invariant</th></tr></thead><tbody><tr><td>Main menu / profile load</td><td>Play opens world selection with the local profile&#39;s saved state. A local profile is not an authenticated identity or another phone&#39;s recovery mechanism.</td></tr><tr><td>World selection</td><td>Show three named cards, progress out of 13, and collection/review status. Locked cards explain their preceding-world requirement rather than loading their islands.</td></tr><tr><td>Tutorial</td><td>First-visit NPC introduces movement, Interact, Quest, Encyclopedia, and Pause. Lesson interactions begin after orientation; remember it per world.</td></tr><tr><td>Exploration</td><td>Joystick and action buttons work in the compact 3D island. Only the current lesson advances, even when the player reaches later objects.</td></tr><tr><td>Quest log</td><td>Show the thirteen ordered lessons, completed/current/locked state, and current prerequisite step and landmark hint.</td></tr><tr><td>Ordinary lesson</td><td>Interact opens meaning and example. Record requests a saved entry; accidental contact does not complete it.</td></tr><tr><td>Minigame prerequisites</td><td>Follow the GDD&#39;s item/NPC/facility order. Missing steps explain what remains; required quest items cannot be spent or lost.</td></tr><tr><td>Minigame</td><td>Run one of nine distinct activities in its separate scene. Retry stays there; Exit returns to its originating island without awarding the lesson.</td></tr><tr><td>Pending completion</td><td>Block duplicate commands. Show Recorded only after the entry save succeeds; failures retain a safe retry route.</td></tr><tr><td>Encyclopedia</td><td>Group 39 entries into three world categories, with alphabetical display independent of teaching order. Browsing never grants collection credit.</td></tr><tr><td>Collection complete</td><td>Show 13/13 recorded and Review required. Exploring and leaving remain possible, but the next world stays locked.</td></tr><tr><td>Required review</td><td>Use the approved completion policy, then save completion and unlock consistently. All 13 required questions must be corrected and successfully saved.</td></tr><tr><td>Pause / overlays / background</td><td>Suspend inappropriate input and clear held joystick state. Resume to a usable state and the last successful checkpoint after interruption.</td></tr><tr><td>Journey complete</td><td>All three required reviews and 39 entries are complete. Offer revisits without claiming mastery or learning improvement.</td></tr></tbody></table><p>The approved rule is 13 questions per world, one per lesson, with correction retries until all are correct. An abandoned review restarts all 13 questions in a new attempt; first responses remain separate from corrected completion. The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">GDD</a> owns lesson assignments and activity rules; the <a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">technical checklist</a> owns later persistence and device verification expectations.</p><h2 id="historical-flow">Historical flow<a class="header-anchor" href="#historical-flow" aria-label="Link to this section">​</a></h2><p>The earlier October 23 route progressed through wallet reward/purchase, repair of the same record, and beacon restoration. That economy-led route is superseded and is not the current UI target. Historical V2 definitions in <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/requirements/product-requirements.html#historical-v2-requirements">product acceptance</a> preserve its context.</p></div>`,1)])])}const m=t(i,[["render",a]]);export{u as __pageData,m as default};
